          [("What is a density-dependent factor?", "A factor, such as disease or competition for food, whose effect increases as the population gets denser."),
           ("Why do predator and prey numbers rise and fall in cycles?", "More prey means more food for predators; then predators eat more prey, prey fall, and predators fall after them.")],
